/**
 * A small inline trend line beside a number (`design/components/sparkline.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/sparkline.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import { claimSlot, createDerived, sparklineGeometry, type Defaults } from '@polymorph/solid'
import styles from '@polymorph/recipes/charts/sparkline.module.css'

export interface SparklineProps {
  /**
   * The values in chronological order, as the app supplies them; the Sparkline never sorts. It
   * is designed for about twelve points. `[]` or a single point renders nothing, because a trend
   * needs two.
   */
  data: readonly number[]
  /**
   * The accessible name, which should state the trend, e.g. "First response, trending down".
   * There is no table twin, so this is all a screen reader gets.
   */
  label: string
  /**
   * `sm` matches the type scale (Stat rows, table cells); `md` suits a larger tile.
   */
  size?: 'sm' | 'md'
}

/** A small inline trend line beside a number. */
export default function Sparkline(given: SparklineProps): JSX.Element {
  const props = mergeProps({ size: 'sm' } as Defaults<SparklineProps, 'size'>, claimSlot(given))
  const drawing = createDerived(() => sparklineGeometry(props.data))
  return (
    <>
      {drawing.value !== null ? (
        <span
          class={styles.spark}
          data-size={props.size}
          role="img"
          aria-label={props.label}
          data-member="sparkline"
        >
          {/* svg */}
          <svg
            class={styles.svg}
            viewBox={drawing.value.viewBox}
            preserveAspectRatio="none"
            aria-hidden="true"
            {...{ focusable: 'false' }}
          >
            {/* line */}
            <path class={styles.line} d={drawing.value.d} />
            {drawing.value.end !== null ? (
              <circle
                class={styles.end}
                cx={drawing.value.end.x}
                cy={drawing.value.end.y}
                r={drawing.value.end.r}
              />
            ) : null}
          </svg>
        </span>
      ) : null}
    </>
  )
}
